import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.CtrpDQpp.js";const p=JSON.parse('{"title":"WordPress 从入门到精通系统教程","description":"","frontmatter":{},"headers":[],"relativePath":"README.md","filePath":"README.md","lastUpdated":1792595797000}'),s={name:"README.md"};function h(o,t,i,n,l,c){return a(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="wordpress-从入门到精通系统教程" tabindex="-1">WordPress 从入门到精通系统教程 <a class="header-anchor" href="#wordpress-从入门到精通系统教程" aria-label="Permalink to &quot;WordPress 从入门到精通系统教程&quot;">​</a></h1><blockquote><p>线上文档站：<a href="https://yzhijie.github.io/wordpress-tutorial-site/" target="_blank" rel="noreferrer">https://yzhijie.github.io/wordpress-tutorial-site/</a>（push 到 <code>main</code> 后由 GitHub Actions 自动构建并发布到公开部署仓）</p></blockquote><blockquote><p>一套面向零基础读者、由浅入深的 WordPress 系统教程：从本地环境搭建、内容管理、主题与插件使用，到主题/插件开发、性能与安全优化、迁移与运维，覆盖 <strong>使用者 → 建站者 → 开发者</strong> 的完整成长路径。每章包含「学习目标 → 原理说明 → 点击级操作 → 常见问题 → 总结 → 动手练习」，并配套可直接运行的示例主题、插件与环境配置。</p></blockquote><h2 id="版本基线-2026-年-10-月校对" tabindex="-1">版本基线（2026 年 10 月校对） <a class="header-anchor" href="#版本基线-2026-年-10-月校对" aria-label="Permalink to &quot;版本基线（2026 年 10 月校对）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>推荐版本</th><th>最低可运行</th><th>说明</th></tr></thead><tbody><tr><td>WordPress</td><td><strong>7.1.x</strong>（2026-08 发布）</td><td>6.x</td><td>本教程界面以 7.x 默认后台为准，差异处会标注 6.x</td></tr><tr><td>PHP</td><td><strong>8.3 / 8.4</strong></td><td>7.4（已 EOL，不推荐）</td><td>兼容范围 8.2–8.5；生产环境禁用 8.1 及以下</td></tr><tr><td>MySQL</td><td><strong>8.0+</strong>（8.4 推荐）</td><td>5.5.5</td><td>支持 8.0 / 8.4 / 9.x</td></tr><tr><td>MariaDB</td><td><strong>10.11+</strong>（LTS）</td><td>5.5.5</td><td>兼容 10.11 / 11.4 / 11.8 / 12.x</td></tr><tr><td>Web 服务器</td><td>Apache 2.4 / Nginx 1.24+</td><td>任意支持 PHP 的服务器</td><td>Apache 需启用 <code>mod_rewrite</code></td></tr><tr><td>HTTPS</td><td><strong>强制</strong></td><td>—</td><td>2026 年所有安装均要求 HTTPS</td></tr><tr><td>编辑器</td><td>区块编辑器（Gutenberg）</td><td>—</td><td>经典编辑器以官方插件形式可选安装</td></tr></tbody></table><blockquote><p>数据来源：<a href="https://wordpress.org/about/requirements/" target="_blank" rel="noreferrer">wordpress.org/about/requirements</a> 与 <a href="https://make.wordpress.org/hosting/handbook/compatibility/" target="_blank" rel="noreferrer">Hosting Handbook 兼容矩阵</a>。</p></blockquote><h2 id="适用人群与学习路径" tabindex="-1">适用人群与学习路径 <a class="header-anchor" href="#适用人群与学习路径" aria-label="Permalink to &quot;适用人群与学习路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>读者</th><th>背景</th><th>建议路径</th></tr></thead><tbody><tr><td>零基础建站者</td><td>不会写代码，想做博客/企业站/电商站</td><td>模块一 → 模块二 → 模块三 → 模块四（选读）→ 模块七</td></tr><tr><td>内容运营</td><td>只需管理内容与评论</td><td>模块一（04、05）→ 模块二 → 模块七（37）</td></tr><tr><td>前端/PHP 开发者</td><td>想做主题与插件开发</td><td>模块一 → 模块三 → 模块四（16）→ <strong>模块五精读</strong> → 模块六</td></tr><tr><td>运维/技术负责人</td><td>负责部署、性能、安全与迁移</td><td>模块一（02、03）→ 模块六 → 模块七，并参考 <code>examples/config/</code></td></tr></tbody></table><h3 id="难度标识" tabindex="-1">难度标识 <a class="header-anchor" href="#难度标识" aria-label="Permalink to &quot;难度标识&quot;">​</a></h3><ul><li>🟢 <strong>入门</strong>：零门槛，按步骤点击即可完成</li><li>🟡 <strong>进阶</strong>：需要理解基础概念，涉及配置或少量代码</li><li>🔴 <strong>高级</strong>：面向开发者，包含 PHP/JS/SQL 代码与架构决策</li></ul><h2 id="章节索引" tabindex="-1">章节索引 <a class="header-anchor" href="#章节索引" aria-label="Permalink to &quot;章节索引&quot;">​</a></h2><h3 id="模块一-基础入门" tabindex="-1">模块一：基础入门 <a class="header-anchor" href="#模块一-基础入门" aria-label="Permalink to &quot;模块一：基础入门&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章</th><th>标题</th><th>难度</th><th>核心内容</th></tr></thead><tbody><tr><td>01</td><td><a href="./01-introduction">WordPress 平台概述</a></td><td>🟢</td><td>历史背景、版本特性、WordPress.org 与 .com 区别、应用场景</td></tr><tr><td>02</td><td><a href="./02-local-environment">本地环境搭建（Windows/macOS/Linux）</a></td><td>🟢</td><td>XAMPP / MAMP / Local / Docker 四套本地方案</td></tr><tr><td>03</td><td><a href="./03-server-environment">服务器环境与 LAMP/LNMP</a></td><td>🟡</td><td>架构详解、PHP 扩展、MySQL/MariaDB 配置、HTTPS</td></tr><tr><td>04</td><td><a href="./04-installation">标准安装流程</a></td><td>🟢</td><td>程序下载、数据库创建、wp-config、五分钟安装向导</td></tr><tr><td>05</td><td><a href="./05-dashboard">后台管理界面全解析</a></td><td>🟢</td><td>仪表盘、全局设置、五种用户角色与权限体系</td></tr></tbody></table><h3 id="模块二-内容管理" tabindex="-1">模块二：内容管理 <a class="header-anchor" href="#模块二-内容管理" aria-label="Permalink to &quot;模块二：内容管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章</th><th>标题</th><th>难度</th><th>核心内容</th></tr></thead><tbody><tr><td>06</td><td><a href="./06-posts-and-pages">文章与页面</a></td><td>🟢</td><td>内容模型区别、应用场景、置顶/摘要/修订版本</td></tr><tr><td>07</td><td><a href="./07-block-editor">区块编辑器全解析</a></td><td>🟢</td><td>区块体系、常用区块、模式与可复用部件、经典编辑器对比</td></tr><tr><td>08</td><td><a href="./08-media-library">媒体库高级管理</a></td><td>🟢</td><td>上传规范、多尺寸图像、图片优化、附件页面</td></tr><tr><td>09</td><td><a href="./09-taxonomies">分类法系统</a></td><td>🟡</td><td>分类与标签规划、自定义分类法、SEO 与信息架构</td></tr><tr><td>10</td><td><a href="./10-comments">评论系统深度配置</a></td><td>🟡</td><td>审核机制、反垃圾、讨论设置、评论模板定制</td></tr></tbody></table><h3 id="模块三-主题应用" tabindex="-1">模块三：主题应用 <a class="header-anchor" href="#模块三-主题应用" aria-label="Permalink to &quot;模块三：主题应用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章</th><th>标题</th><th>难度</th><th>核心内容</th></tr></thead><tbody><tr><td>11</td><td><a href="./11-theme-ecosystem">主题生态系统</a></td><td>🟢</td><td>官方主题库、商业主题、经典主题与区块主题、选择标准</td></tr><tr><td>12</td><td><a href="./12-theme-management">主题安装与管理</a></td><td>🟢</td><td>后台安装、上传 ZIP、FTP、更新机制与回滚</td></tr><tr><td>13</td><td><a href="./13-customizer">自定义器与站点编辑器</a></td><td>🟡</td><td>站点标识、颜色方案、排版、菜单、全站编辑（FSE）入门</td></tr><tr><td>14</td><td><a href="./14-responsive-design">响应式设计原理与实践</a></td><td>🟡</td><td>移动优先、断点设置、跨设备测试工具</td></tr><tr><td>15</td><td><a href="./15-child-themes">子主题创建与应用</a></td><td>🟡</td><td>继承机制、样式覆盖、模板覆盖、安全更新策略</td></tr></tbody></table><h3 id="模块四-插件应用" tabindex="-1">模块四：插件应用 <a class="header-anchor" href="#模块四-插件应用" aria-label="Permalink to &quot;模块四：插件应用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章</th><th>标题</th><th>难度</th><th>核心内容</th></tr></thead><tbody><tr><td>16</td><td><a href="./16-plugin-architecture">插件架构与工作原理</a></td><td>🟡</td><td>动作钩子（Action）与过滤器（Filter）、插件加载流程</td></tr><tr><td>17</td><td><a href="./17-plugin-management">插件安装与版本管理</a></td><td>🟢</td><td>官方库、第三方插件、自动更新、WP-CLI 管理</td></tr><tr><td>18</td><td><a href="./18-security-plugins">安全类插件配置</a></td><td>🟡</td><td>Wordfence / Sucuri、防火墙、恶意代码扫描、登录保护</td></tr><tr><td>19</td><td><a href="./19-performance-plugins">性能优化插件</a></td><td>🟡</td><td>页面缓存、对象缓存、数据库优化、资源压缩合并</td></tr><tr><td>20</td><td><a href="./20-seo-plugins">SEO 插件高级设置</a></td><td>🟡</td><td>Yoast SEO、标题/元数据、XML 站点地图、结构化数据</td></tr><tr><td>21</td><td><a href="./21-feature-plugins">功能增强插件推荐</a></td><td>🟡</td><td>表单、会员、电商（WooCommerce）、多语言、缓存外的提效插件</td></tr></tbody></table><h3 id="模块五-高级定制-开发" tabindex="-1">模块五：高级定制（开发） <a class="header-anchor" href="#模块五-高级定制-开发" aria-label="Permalink to &quot;模块五：高级定制（开发）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章</th><th>标题</th><th>难度</th><th>核心内容</th></tr></thead><tbody><tr><td>22</td><td><a href="./22-theme-dev-basics">主题开发基础</a></td><td>🔴</td><td>开发环境、WP 编码标准、调试体系、版本控制工作流</td></tr><tr><td>23</td><td><a href="./23-template-hierarchy">主题文件结构与模板层次</a></td><td>🔴</td><td>核心模板、Template Hierarchy、functions.php、区块主题结构</td></tr><tr><td>24</td><td><a href="./24-custom-templates">自定义模板与 WP_Query</a></td><td>🔴</td><td>页面模板、分类模板、主查询与自定义查询、查询优化</td></tr><tr><td>25</td><td><a href="./25-asset-loading">CSS/JS 定制：Enqueue 机制</a></td><td>🔴</td><td>wp_enqueue、条件加载、版本管理、前端构建工具集成</td></tr><tr><td>26</td><td><a href="./26-widget-development">小工具开发全流程</a></td><td>🔴</td><td>注册、回调、表单、保存验证、区块化小工具</td></tr><tr><td>27</td><td><a href="./27-custom-post-types">自定义文章类型与分类法</a></td><td>🔴</td><td>register_post_type 参数、固定链接、模板、查询与 REST</td></tr><tr><td>28</td><td><a href="./28-settings-api">主题选项面板与 Settings API</a></td><td>🔴</td><td>Settings API、选项注册、验证回调、Customizer 深度用法</td></tr></tbody></table><h3 id="模块六-网站优化" tabindex="-1">模块六：网站优化 <a class="header-anchor" href="#模块六-网站优化" aria-label="Permalink to &quot;模块六：网站优化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章</th><th>标题</th><th>难度</th><th>核心内容</th></tr></thead><tbody><tr><td>29</td><td><a href="./29-performance">性能优化完整方案</a></td><td>🔴</td><td>服务器/PHP/数据库/前端全栈优化、缓存层级设计</td></tr><tr><td>30</td><td><a href="./30-image-optimization">图片优化策略</a></td><td>🟡</td><td>格式选择（WebP/AVIF）、压缩、响应式图片、懒加载</td></tr><tr><td>31</td><td><a href="./31-advanced-seo">高级 SEO 技术</a></td><td>🟡</td><td>结构化数据、面包屑、canonical、robots、内链策略</td></tr><tr><td>32</td><td><a href="./32-security">安全防护体系</a></td><td>🔴</td><td>文件权限、SQL 注入/XSS/CSRF 防护、加固清单</td></tr><tr><td>33</td><td><a href="./33-speed-monitoring">速度测试与持续监控</a></td><td>🟡</td><td>PageSpeed/WebPageTest、Core Web Vitals、监控告警</td></tr></tbody></table><h3 id="模块七-迁移与维护" tabindex="-1">模块七：迁移与维护 <a class="header-anchor" href="#模块七-迁移与维护" aria-label="Permalink to &quot;模块七：迁移与维护&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章</th><th>标题</th><th>难度</th><th>核心内容</th></tr></thead><tbody><tr><td>34</td><td><a href="./34-backup">备份策略与工具</a></td><td>🟡</td><td>完整/增量备份、文件+数据库、自动调度、异地备份</td></tr><tr><td>35</td><td><a href="./35-migration">数据迁移全流程</a></td><td>🟡</td><td>本地到服务器、服务器间迁移、域名变更清单</td></tr><tr><td>36</td><td><a href="./36-database-migration">数据库迁移与序列化数据</a></td><td>🔴</td><td>导出导入、WP-CLI search-replace、序列化数据原理</td></tr><tr><td>37</td><td><a href="./37-maintenance">日常维护清单</a></td><td>🟢</td><td>更新管理、维护模式、安全扫描、月度/季度任务</td></tr><tr><td>38</td><td><a href="./38-troubleshooting">故障排查与应急恢复</a></td><td>🔴</td><td>白屏、500/502、数据库连接错误、日志分析、应急流程</td></tr></tbody></table><h2 id="配套资源" tabindex="-1">配套资源 <a class="header-anchor" href="#配套资源" aria-label="Permalink to &quot;配套资源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>路径</th><th>说明</th></tr></thead><tbody><tr><td>🧩 配套示例项目</td><td><a href="./examples/README">examples/</a></td><td>Docker 本地环境 + 教学主题 + 子主题 + 区块主题 + 演示插件 + 服务器配置 + 运维脚本</td></tr><tr><td>📝 术语表</td><td><a href="./glossary">glossary.md</a></td><td>中英对照术语解释，建议阅读时随时查阅</td></tr><tr><td>⚡ 速查卡</td><td><a href="./cheatsheet">cheatsheet.md</a></td><td>模板层次、钩子、WP-CLI、wp-config、排障命令一页速查</td></tr><tr><td>✏️ 练习答案</td><td><a href="./exercises/README">exercises/</a></td><td>各章练习题汇总与参考答案</td></tr><tr><td>🖼️ 截图清单</td><td><a href="./screenshots/README">screenshots/README.md</a></td><td>全教程截图占位清单、拍摄与标注规范</td></tr><tr><td>🎬 视频脚本</td><td><a href="./videos/storyboards">videos/storyboards.md</a></td><td>关键操作的教学视频分镜脚本（可直接照着录屏）</td></tr></tbody></table><h2 id="在线版-pdf-视频交付说明" tabindex="-1">在线版 / PDF / 视频交付说明 <a class="header-anchor" href="#在线版-pdf-视频交付说明" aria-label="Permalink to &quot;在线版 / PDF / 视频交付说明&quot;">​</a></h2><ul><li><p><strong>在线版本</strong>：本教程基于 VitePress 构建。在本目录执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 或 npm install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 本地预览 http://localhost:5173</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 产物输出到 .vitepress/dist，可部署到 GitHub Pages / Netlify / Vercel</span></span></code></pre></div></li><li><p><strong>PDF 版本</strong>：<code>pnpm docs:build</code> 后用浏览器打开生成的静态站点，通过「打印 → 另存为 PDF」逐模块导出；或使用社区方案 <code>vitepress-export-pdf</code>。详见 <a href="./videos/storyboards">videos/storyboards.md</a> 末尾的导出指引。</p></li><li><p><strong>教学视频</strong>：本仓库提供关键操作的<strong>分镜脚本与旁白文案</strong>（<a href="./videos/storyboards">videos/storyboards.md</a>），使用 OBS / QuickTime / WPS 录屏按脚本录制即可，建议分辨率 1920×1080、30fps。</p></li><li><p><strong>截图</strong>：教程中以 <code>screenshots/</code> 下的规范文件名预留了截图位，按 <a href="./screenshots/README">screenshots/README.md</a> 的拍摄清单补图即可，图片放入对应路径后在线版自动显示。</p></li></ul><h2 id="如何使用本教程" tabindex="-1">如何使用本教程 <a class="header-anchor" href="#如何使用本教程" aria-label="Permalink to &quot;如何使用本教程&quot;">​</a></h2><ol><li><strong>第一遍按顺序学</strong>：每章开头有明确学习目标，结尾有 3–5 道动手练习，练习编号格式为 <code>练-CC-NN</code>（CC=章节号）。</li><li><strong>边学边练</strong>：配合 <a href="./examples/README">examples/</a> 的 Docker 环境，所有代码均可直接复制到本地运行。</li><li><strong>先跑通再优化</strong>：每遇到一个技术点，先按「操作方法」复现，再回头读「原理说明」，最后看「常见问题」避坑。</li><li><strong>卡住时查附录</strong>：术语表查概念、速查卡查函数、第 38 章查报错。</li></ol>`,31)])])}const g=d(s,[["render",h]]);export{p as __pageData,g as default};
